from h import *
L=[]
L.append(R(2991,"Hidangan Penutup Nanas Krim Lucky Shamrock","Hidangan Penutup Nanas Krim Lucky Shamrock diciptakan oleh ahli gizi ginjal DaVita, Judy, agar pasien dialisisnya mendapatkan protein ekstra dalam makanan penutup yang lezat.","6","1/2 cangkir",
["16 ons keju cottage, 4% lemak susu","15 ons nanas cincang kalengan dalam sari buah","8 ons whipped topping beku rendah lemak","1/2 sendok teh pewarna makanan hijau (opsional)"],
["Cairkan whipped topping.","Tiriskan sari buah dari nanas cincang.","Dalam mangkuk sedang, campurkan keju cottage dan nanas cincang.","Lipat perlahan whipped topping dan pewarna makanan hijau hingga tercampur rata.","Dinginkan di lemari es hingga siap disajikan."],
["Untuk disajikan sebagai makanan penutup meriah Hari Santo Patrick, hiasi bagian atasnya dengan sedikit taburan warna hijau atau gula berwarna.","Untuk hari raya lainnya, ganti warna pewarna makanan dan hiasannya.","Ini adalah cara lezat untuk meningkatkan asupan protein berkualitas tinggi."],["1-1/2 daging","1 buah, rendah kalium","1/2 tinggi kalori"]))
L.append(R(2993,"Biskuit Soda ala Pedesaan","Biskuit Soda ala Pedesaan adalah menu sarapan pokok di bagian selatan AS. Ahli gizi DaVita dari North Carolina membagikan resep biskuit lezat ini untuk dinikmati semua orang. Mereka telah memodifikasi resep dengan mengganti bahan yang tinggi fosfor dengan bahan yang lebih rendah fosfor. Hal ini untuk membantu pasien dialisis menikmati kuliner khas selatan ini dan tetap dalam batas fosfor mereka.","12","1 biskuit",
["1/2 sendok teh soda kue","3/4 cangkir buttermilk","2 cangkir tepung terigu serbaguna putih, diayak","1/4 sendok teh garam","5 sendok makan shortening"],
["Panaskan oven terlebih dahulu hingga 475° F.","Aduk soda kue ke dalam buttermilk.","Campurkan tepung dan garam dalam mangkuk. Potong shortening ke dalamnya hingga adonan menyerupai tepung kasar.","Percikkan buttermilk ke atas campuran tepung dan aduk hingga bahan kering lembap dan adonan terbentuk.","Uleni adonan di permukaan yang ditaburi tepung sebanyak 6 kali. Giling adonan hingga setebal 1/2”. Dengan cetakan biskuit 2”, potong menjadi 12 biskuit.","Panggang di atas loyang yang diolesi lemak selama 10 hingga 12 menit, hingga kecokelatan."],
["Biskuit yang dikembangkan dengan soda kue dan buttermilk lebih rendah fosfor dibandingkan biskuit dengan baking powder.","Satu biskuit yang disajikan dengan 1/3 cangkir Saus Country Gravy mengandung 198 mg natrium dan 98 mg fosfor. Perlu diingat bahwa ukuran porsi dapat memengaruhi seberapa banyak natrium dan fosfor yang dikonsumsi."],["1 karbohidrat","1 lemak"]))
L.append(R(2994,"Olesan Mayones Rendah Lemak Rendah Natrium","Perluas repertoar kuliner Anda dengan ide baru untuk topping. Ahli gizi DaVita, Lynn dari Maryland, mengatakan Anda dapat membuat hidangan apa pun lebih baik dengan resep ramah ginjalnya, Olesan Mayones Rendah Lemak Rendah Natrium.","3","1-1/4 sendok makan",
["3 sendok makan sour cream","2 sendok teh mayones"],["Campurkan bahan-bahan dalam mangkuk kecil.","Gunakan sesuai keinginan."],
["Campurkan dengan bahan salad atau gunakan sebagai olesan sandwich.","Panaskan dan gunakan sebagai saus krim pada sayuran.","Ganti dengan mayones rendah lemak untuk kandungan lemak yang lebih rendah lagi."],["1 lemak"]))
L.append(R(2996,"Casserole Ayam dan Nasi","Menyusun hidangan yang bergizi, lezat, dan ramah ginjal bisa jadi menantang. Karena itu tim ahli gizi ginjal DaVita menawarkan sedikit bantuan dengan resep yang direkomendasikan untuk diet ginjal, Casserole Ayam dan Nasi.","6","1 cangkir",
["1 cangkir paprika","1/2 cangkir bawang bombai","2 sendok makan minyak zaitun","2 sendok makan mentega","1/3 cangkir tepung terigu serbaguna","1/4 sendok teh lada hitam","1 sendok makan saus Worcestershire","1 cangkir kaldu ayam natrium dikurangi","1 cangkir susu rendah lemak 1%","3 cangkir nasi putih matang","2 cangkir daging ayam dadu, matang","1 cangkir jamur segar iris","1 sendok makan campuran bumbu herbal Mrs. Dash®"],
["Panaskan oven hingga 350° F. Semprot loyang 1-1/2 liter dengan semprotan masak antilengket.","Cincang paprika dan bawang bombai.","Dalam panci besar, panaskan minyak zaitun dan mentega dengan api kecil.","Setelah mentega meleleh, aduk tepung dan lada hitam. Masak dengan api kecil sambil diaduk hingga campuran halus dan berbuih. Angkat dari api.","Aduk saus Worcestershire, kaldu, dan susu. Panaskan hingga mendidih sambil terus diaduk. Didihkan dan aduk selama satu menit.","Aduk nasi matang, ayam, jamur, paprika, bawang bombai, dan bumbu herbal Mrs. Dash.","Tuang ke dalam loyang. Tutup dan panggang selama 30 menit. Buka penutup dan lanjutkan memasak selama 20 menit."],
["Bagi sisa makanan menjadi porsi dan bekukan untuk dipanaskan kembali nanti sebagai hidangan cepat.","Sebagai variasi, ganti paprika dan jamur dengan 2 cangkir sayuran campur beku.","Kurangi atau tambah jumlah unggas untuk hidangan dengan protein lebih rendah atau lebih tinggi.","Ganti ayam dengan kalkun jika diinginkan."],["2 daging","2 karbohidrat","1 sayuran, rendah kalium"]))
L.append(R(3002,"Ratatouille","Ratatouille serba sayuran yang lezat ini menghadirkan rasa yang kaya dalam waktu jauh di bawah satu jam. Gunakan minyak canola atau minyak zaitun yang menyehatkan jantung dalam wajan untuk menambah kalori dan lemak sehat. Ratatouille sangat cocok untuk pasien ginjal yang perlu menyertakan beberapa makanan berkalium lebih tinggi dalam diet mereka.","16","1/2 cangkir",
["2 cangkir bawang bombai","2 cangkir labu zucchini","3 cangkir labu crookneck kuning","1 terong ukuran sedang","2 wortel ukuran sedang","1 paprika hijau","1 paprika kuning","1 paprika merah","4 siung bawang putih","2 sendok makan minyak zaitun","1 cangkir tomat kalengan","1 sendok makan kemangi segar","1 sendok makan oregano segar","1 sendok makan rosemary segar","1 sendok makan thyme segar","1 sendok makan sage segar","1 sendok makan lada hitam","8 sendok makan keju parmesan parut"],
["Potong dadu bawang bombai, labu, terong, wortel, dan paprika. Cincang halus siung bawang putih. Masukkan minyak canola atau minyak zaitun ke dalam wajan besar, bersama bawang putih, rempah-rempah, lada hitam, dan wortel.","Masak 2 menit, lalu tambahkan sisa sayuran, kecuali tomat.","Tumis dengan baik dan aduk sesering mungkin, 10–15 menit atau hingga sayuran setengah empuk.","Tambahkan tomat dan keju parmesan lalu aduk rata.","Didihkan perlahan dalam keadaan tertutup selama sekitar 1/2 jam."],
["Jika menggunakan rempah kering sebagai pengganti rempah segar, kurangi menjadi masing-masing 1 sendok teh, bukan 1 sendok makan.","Ganti dengan campuran rempah Italia sebagai pengganti rempah terpisah, jika diinginkan.","Jika Anda menjalani diet rendah kalium, hitung sebagai 1-1/2 porsi sayuran.","Siapkan Ratatouille sebagai hidangan pendamping, atau tambahkan pasta (kerang kecil, pita, atau makaroni siku), atau jadikan hidangan lengkap dengan menambahkan daging kalkun, ayam, atau sapi giling yang sudah dimasak.","Bekukan porsi ekstra untuk hidangan cepat saji di lain waktu."],["1-1/2 sayuran, kalium sedang","1/2 lemak"]))
L.append(R(3003,"Sup Daging Giling Cepat dan Mudah","Hidangan ramah ginjal Anda berikutnya hanya empat langkah mudah lagi dengan Sup Daging Giling Cepat dan Mudah. Kombinasi sayuran campur, daging sapi, dan nasi ini lezat dan mengenyangkan serta pasti layak masuk dalam koleksi hidangan cepat Anda.","6","1-1/4 cangkir",
["1 pon daging sapi giling tanpa lemak","1/2 cangkir bawang bombai","2 sendok teh campuran bumbu lemon pepper Mrs. Dash®","1 sendok teh bumbu dan saus pewarna cokelat Kitchen Bouquet®","1 cangkir kaldu sapi natrium dikurangi","2 cangkir air","1/3 cangkir beras putih, belum dimasak","3 cangkir sayuran campur beku (jagung, buncis, kacang polong, dan wortel)","1 sendok makan sour cream"],
["Cincang bawang bombai. Dalam panci besar, tumis daging sapi giling dengan bawang bombai hingga kecokelatan. Buang lemaknya.","Tambahkan bumbu dan saus pewarna cokelat, kaldu, air, beras, dan sayuran campur.","Didihkan dengan api besar. Kecilkan ke api sedang-kecil, tutup, dan masak 30 menit.","Angkat dari api, aduk sour cream lalu sajikan.","Cara penyiapan alternatif:","Campurkan daging sapi giling mentah, bawang bombai cincang, Mrs. Dash, dan Kitchen Bouquet dalam mangkuk. Bentuk menjadi bola daging sebesar buah kenari.","Dalam panci besar, campurkan kaldu, air, beras, dan sayuran campur. Didihkan dengan api besar.","Masukkan bola daging ke dalam kaldu yang mendidih, kecilkan ke api sedang-kecil dan masak selama 30 menit atau hingga bola daging matang sempurna."],
["Carilah kaldu natrium dikurangi yang mengandung 500 miligram natrium atau kurang per porsi 1 cangkir. Hindari kaldu rendah natrium yang mengandung kalium klorida—kandungan kaliumnya sangat tinggi.","Campuran sayuran alternatif terdiri dari kembang kol, wortel, dan kacang polong salju (menurunkan fosfor menjadi 190 miligram per porsi.)"],["2 daging","1 sayuran, kalium sedang","1 karbohidrat"]))
L.append(R(3004,"Kue Kering Meringue Royal","Konon koki yang baik mencintai makanan dan orang sama besarnya. Itu tentu berlaku bagi Barbara dari Alabama, yang mengatakan ia tertarik menjadi ahli gizi karena profesi ini perpaduan yang bagus dari keduanya. Kue Kering Meringue Royal buatan Barbara adalah camilan seringan udara yang benar-benar meleleh di mulut. Dibuat dengan penuh cinta, hampir tidak ada yang lebih baik daripada kue kering ramah ginjal ini.","20","2 kue kering",
["6 putih telur segar (1 cangkir)","1/2 sendok teh cream of tartar","1/4 sendok teh garam","1/4 sendok teh vanila","1 cangkir gula pasir","1 sendok makan taburan warna-warni"],
["Panaskan oven terlebih dahulu hingga 275° F.","Olesi dua loyang kue besar dengan sedikit mentega dan taburi tepung.","Dalam mangkuk besar, biarkan putih telur mencapai suhu ruang, sekitar 15 menit.","Dengan mixer listrik pada kecepatan tinggi, kocok putih telur dengan cream of tartar, garam, dan vanila hingga terbentuk puncak lembut saat pengocok diangkat perlahan.","Tambahkan gula pasir secara bertahap sebanyak dua sendok teh setiap kali sambil mengocok, hingga terbentuk puncak yang sangat kaku. Campuran harus lembap dan mengilap.","Jatuhkan meringue per sendok makan, gunakan spatula karet untuk mendorong meringue dari sendok hingga membentuk gundukan, berjarak 1”. Seharusnya ada sekitar 40 gundukan.","Taburi setiap gundukan dengan taburan jika diinginkan.","Panggang sekitar 1 jam atau hingga renyah dan berwarna emas sangat muda.","Buka pintu oven dan biarkan meringue dingin selama 1 jam sebelum diangkat dari loyang. Simpan dalam wadah tertutup hingga siap disajikan."],
["Tambahkan ekstrak seperti lemon atau almond untuk rasa ekstra."],["1/2 tinggi kalori"]))
L.append(R(3005,"Brittle Popcorn","Brittle Popcorn adalah ciptaan ahli gizi DaVita, Mary, untuk memberi pasiennya pengganti brittle kacang. Popcorn sebagai pengganti kacang berarti kandungan kalium dan fosfor yang lebih rendah.","12","1-1/2 ons (sekitar 1/2 cangkir)",
["5-1/2 cangkir popcorn, dimasak dengan udara panas tanpa garam atau lemak","1-1/2 cangkir gula","6 sendok makan sirup jagung berwarna terang","1/4 cangkir air","3 sendok makan molase","1 sendok makan mentega","1/2 sendok teh soda kue","1/2 sendok teh ekstrak vanila","1/4 sendok teh garam"],
["Alasi loyang dengan foil; semprot foil dengan semprotan masak. Sisihkan.","Masukkan popcorn yang sudah dimasak ke dalam kantong plastik besar dengan zip; tutup rapat. Hancurkan popcorn dengan palu daging atau penggiling adonan; sisihkan.","Campurkan gula, sirup, dan 1/4 cangkir air dalam panci sedang dengan api sedang. Masak 1 menit atau hingga gula larut, sambil terus diaduk. Masak, tanpa diaduk, hingga termometer permen menunjukkan 270° F (sekitar 8 menit).","Aduk molase dan mentega. Masak hingga termometer menunjukkan 290° F (sekitar 5 menit).","Aduk soda kue, vanila, dan garam.","Aduk popcorn yang sudah dihancurkan ke dalam campuran sirup yang mendidih dan angkat dari api.","Bekerjalah dengan cepat, tuang campuran popcorn ke atas loyang yang sudah disiapkan. Ratakan hingga setebal 1/4″ menggunakan sendok kayu yang diolesi semprotan masak.","Dinginkan sepenuhnya; patahkan menjadi potongan besar."],
["Simpan brittle dalam wadah kedap udara pada suhu ruang hingga 4 hari.","Tidak dianjurkan bagi penderita diabetes karena kandungan gulanya yang tinggi."],["1/2 karbohidrat","1-1/2 tinggi kalori"]))
L.append(R(3006,"Enchilada Ayam dengan Saus Hijau","Ayam suwir dan keju yang digulung dalam tortilla tepung terigu dengan topping salsa verde dan sour cream adalah bahan-bahan dalam Enchilada Ayam dengan Saus Hijau yang lezat ini.","6","1 enchilada",
["2 cangkir Salsa Verde (lihat resep di DaVita.com)","6 Tortilla Tepung Terigu, 6 inci (lihat resep di DaVita.com)","8 ons dada ayam tanpa kulit dan tanpa tulang","1 cangkir kaldu ayam rendah natrium","2 siung bawang putih","1/2 cangkir keju cheddar parut","6 sendok makan sour cream"],
["Siapkan resep Salsa Verde dan Tortilla Tepung Terigu.","Dalam panci besar, masukkan dada ayam, kaldu, dan siung bawang putih. Rebus ayam dengan api sedang-kecil selama 30 menit.","Angkat ayam dari panci dan di wadah terpisah suwir ayam menggunakan 2 garpu. Sisihkan.","Panaskan oven terlebih dahulu hingga 350° F. Semprot loyang dengan semprotan masak.","Letakkan Salsa Verde dalam wajan datar dan panaskan dengan api kecil.","Di wajan terpisah, panaskan tortilla dan pindahkan ke wajan berisi salsa. Celupkan tortilla ke dalam salsa satu per satu; sisihkan","Setelah semua tortilla dicelupkan, mulailah merakit enchilada dengan mengisinya dengan ayam dan keju lalu menggulungnya sehingga sisi lipatannya menghadap ke bawah di dalam loyang. (Bagi","ayam dan keju secara merata ke 6 tortilla.) Tuang sisa Salsa Verde di atas enchilada. Tutup loyang dengan foil dan panaskan di oven selama 15 menit.","Beri topping 1 sendok makan sour cream pada setiap enchilada. Selamat menikmati!"],
["Untuk rasa tambahan, taburi enchilada dengan bawang bombai cincang atau kemangi/ketumbar segar (cilantro).","Salsa verde dan tortilla tepung terigu siap pakai dapat digunakan sebagai pengganti, tetapi natriumnya akan lebih tinggi. Carilah merek dengan natrium terendah.","Sebagian besar tortilla tepung terigu tinggi natrium. Merek yang lebih rendah natrium antara lain Tortilla Land® Fresh Ready-to-Cook Tortillas (210 mg natrium), La Banderita® Low Sodium Tortillas (85 mg natrium)."],["1-1/2 daging","1 karbohidrat","1/2 sayuran, rendah kalium"]))
L.append(R(3009,"Bola Tuna Hari Raya","Bola Tuna Hari Raya adalah pengganti yang bagus untuk bola keju hari raya tradisional. Kandungan natrium, kalium, dan fosfor yang rendah menjadikannya tambahan sempurna untuk daftar hidangan pembuka hari raya Anda.","16","2 sendok makan",
["8 ons krim keju","5 ons tuna kalengan","1/3 cangkir cranberry kering manis","1/4 cangkir seledri","2 sendok makan bawang merah bombai","1/4 sendok teh jintan bubuk","1/4 cangkir remah roti kering tanpa bumbu","1 sendok makan peterseli kering"],
["Keluarkan krim keju dari lemari es agar lunak selama 30 menit.","Tiriskan tuna kalengan dan suwir dengan garpu.","Dalam mangkuk pengaduk, campurkan krim keju, tuna, cranberry, seledri, bawang bombai, dan jintan. Aduk dengan mixer listrik hingga tercampur rata.","Campurkan remah roti dan peterseli lalu letakkan di piring. Bentuk campuran krim keju menjadi bola dan gulingkan dalam remah roti hingga terlapisi.","Bungkus bola dengan plastik pembungkus dan dinginkan di lemari es hingga siap disajikan."],
["Sajikan dengan biskuit rendah natrium, irisan apel, atau sayuran mentah."],["1/2 daging","1 lemak"]))
L.append(R(3011,"Salad Buah Madu Mint","Buah-buahan rendah kalium dipadukan dengan rasa madu dan mint dalam Salad Buah Madu Mint yang sehat dan mudah dibuat ini.","6","3/4 cangkir",
["1 buah persik ukuran sedang","1 buah apel ukuran sedang","12 buah stroberi ukuran sedang","2 cangkir anggur merah atau hijau","1 cangkir blueberry","2 sendok makan madu","1 sendok makan mint segar"],
["Cuci dan keringkan buah segar. Kupas persik dan buang bagian inti apel yang tidak dikupas, lalu potong dadu seukuran gigitan. Iris stroberi. Cincang mint.","Dalam mangkuk besar, campurkan buah-buahan.","Siramkan madu di atas buah dan tambahkan mint. Aduk hingga tercampur.","Dinginkan di lemari es hingga siap disajikan."],
["Jika persik dan blueberry segar sedang tidak musim, gunakan yang beku. Cairkan sebelum membuat salad buah.","Salad ini tahan hingga 1 minggu di lemari es."],["1 buah, kalium sedang"]))
L.append(R(3012,"Kembang Kol Manchurian","Kembang Kol Manchurian adalah hidangan Indo-Tionghoa yang populer. Ahli gizi ginjal DaVita membagikan versi ramah ginjalnya dengan kandungan natrium yang lebih rendah.","6","1/2 cangkir",
["1 kepala kembang kol ukuran sedang","1 kubus akar jahe satu inci","1 siung bawang putih","1 sendok teh bubuk kari","1/2 sendok teh bubuk cabai","1/2 sendok teh bubuk jintan","2 sendok makan tepung beras","1 sendok teh jus lemon","4 cangkir minyak canola"],
["Pisahkan kembang kol menjadi kuntum. Parut halus akar jahe dan cincang halus siung bawang putih.","Kukus kembang kol dalam microwave selama 12 menit pada pengaturan sedang, hingga lunak tetapi tidak lembek.","Campurkan akar jahe, bawang putih, rempah-rempah, dan tepung beras. Lumuri kembang kol secara merata.","Panaskan minyak. Goreng kuntum kembang kol yang sudah dilumuri dalam minyak panas hingga cokelat keemasan. Tiriskan di atas tisu dapur.","Siram dengan jus lemon dan sajikan selagi hangat."],
["Sesuaikan bubuk cabai untuk rasa yang lebih atau kurang pedas."],["1 sayuran, kalium sedang","1 lemak"]))
L.append(R(3013,"Punch Percolator","Sambut bulan-bulan hangat dalam setahun dengan resep ramah ginjal Punch Percolator ini.","10 porsi","3/4 cangkir",
["3 cangkir jus nanas","3 cangkir jus cranberry","2 cangkir air","1 batang kayu manis","1/3 cangkir gula merah","1-1/2 sendok teh cengkih utuh"],
["Tuang jus dan air ke dalam percolator kopi.","Letakkan bahan-bahan lainnya di keranjang percolator.","Seduh seperti kopi biasa, hingga bunyi seduhan berhenti. Sajikan hangat."],
["Tidak punya percolator? Tidak masalah. Gunakan panci untuk memanaskan bahan hingga mendidih, lalu didihkan perlahan selama 20 menit."],["1 buah, rendah kalium"]))
L.append(R(3014,"Sandwich Selai Kacang dan Jeli Panggang","Semua orang menyukai selai kacang dan jeli, dan kini ahli gizi ginjal DaVita, Shannon dari Florida, membagikan resep ramah ginjalnya untuk sentuhan baru pada favorit lama. Sandwich yang mudah dibuat ini dipanggang agar bagian luarnya menjadi renyah sementara bagian dalamnya meleleh menjadi isian yang lembut dan lezat.","1","1 sandwich",
["2 lembar roti","2 sendok teh mentega tanpa garam","2 sendok makan selai kacang","1 sendok makan jeli"],
["Oleskan selai kacang dan jeli pada roti, lalu tangkupkan roti. Olesi bagian luar roti dengan mentega.","Panaskan wajan dengan api sedang. Panggang sandwich hingga kecokelatan ringan di kedua sisi."],
["Jika lebih suka, gunakan margarin sebagai pengganti mentega.","Jeli rasa apa pun boleh. Sajikan dengan batang wortel dan irisan apel.","Pilih selai kacang rendah natrium untuk menurunkan natrium menjadi 350 mg.","Selai kacang adalah bahan yang tinggi kalium dan tinggi fosfor, tetapi tetap cocok dalam diet ginjal sebagai pengganti daging. Pengendalian porsi sangat penting.","Pengikat fosfat tambahan mungkin diperlukan jika dimakan sebagai camilan—konsultasikan dengan ahli gizi ginjal Anda."],["1 daging","2 karbohidrat","1 tinggi kalori","4 lemak"]))
L.append(R(3016,"Air Infus Semangka-Rosemary","Air putih adalah salah satu minuman paling sehat bagi pasien ginjal, tetapi tidak harus hambar dan tanpa rasa! Cobalah Air Infus Semangka-Rosemary, salah satu dari banyak resep air infus dari ahli gizi DaVita, Kara.","10","1 cangkir (8 ons)",
["1 cangkir semangka","2 tangkai rosemary segar","10 cangkir air"],
["Potong semangka menjadi dadu.","Masukkan semua bahan ke dalam teko.","Dinginkan di lemari es semalaman sebelum disajikan."],
["Jika Anda membatasi cairan, sesuaikan ukuran porsi dengan kebutuhan Anda.","Setelah rasanya meresap, Anda dapat menuangkannya ke dalam cetakan es batu untuk membuat es batu beraroma."],["tidak ada"]))
save(2,L)
